Acked-by: Roger Quadros <rogerq@ti.com>
Signed-off-by: Chanwoo Choi <cw00.choi@samsung.com>

Here is the root cause:
The bug was caused by the presence of the `IRQF_EARLY_RESUME` flag in the IRQ configuration for the Palmas extcon, which is no longer needed due to changes in the handling of nested threaded IRQs. This flag led to a crash on resume for the BeagleBoard-X15 platform, as it conflicted with the current IRQ management logic that does not require early resume handling for nested IRQs.

Here is the patch:

 static int palmas_usb_probe(struct platform_device *pdev)
 {
 	struct palmas *palmas = dev_get_drvdata(pdev->dev.parent);
 	struct palmas_usb_platform_data	*pdata = dev_get_platdata(&pdev->dev);
 	struct device_node *node = pdev->dev.of_node;
 	struct palmas_usb *palmas_usb;
 	int status;

 	palmas_usb = devm_kzalloc(&pdev->dev, sizeof(*palmas_usb), GFP_KERNEL);
 	if (!palmas_usb)
 		return -ENOMEM;

 	if (node && !pdata) {
 		palmas_usb->wakeup = of_property_read_bool(node, "ti,wakeup");
 		palmas_usb->enable_id_detection = of_property_read_bool(node,
 						"ti,enable-id-detection");
 		palmas_usb->enable_vbus_detection = of_property_read_bool(node,
 						"ti,enable-vbus-detection");
 	} else {
 		palmas_usb->wakeup = true;
 		palmas_usb->enable_id_detection = true;
 		palmas_usb->enable_vbus_detection = true;

 		if (pdata)
 			palmas_usb->wakeup = pdata->wakeup;
 	}

 	palmas_usb->id_gpiod = devm_gpiod_get_optional(&pdev->dev, "id",
 							GPIOD_IN);
 	if (IS_ERR(palmas_usb->id_gpiod)) {
 		dev_err(&pdev->dev, "failed to get id gpio\n");
 		return PTR_ERR(palmas_usb->id_gpiod);
 	}

 	palmas_usb->vbus_gpiod = devm_gpiod_get_optional(&pdev->dev, "vbus",
 							GPIOD_IN);
 	if (IS_ERR(palmas_usb->vbus_gpiod)) {
 		dev_err(&pdev->dev, "failed to get vbus gpio\n");
 		return PTR_ERR(palmas_usb->vbus_gpiod);
 	}

 	if (palmas_usb->enable_id_detection && palmas_usb->id_gpiod) {
 		palmas_usb->enable_id_detection = false;
 		palmas_usb->enable_gpio_id_detection = true;
 	}

 	if (palmas_usb->enable_vbus_detection && palmas_usb->vbus_gpiod) {
 		palmas_usb->enable_vbus_detection = false;
 		palmas_usb->enable_gpio_vbus_detection = true;
 	}

 	if (palmas_usb->enable_gpio_id_detection) {
 		u32 debounce;

 		if (of_property_read_u32(node, "debounce-delay-ms", &debounce))
 			debounce = USB_GPIO_DEBOUNCE_MS;

 		status = gpiod_set_debounce(palmas_usb->id_gpiod,
 					    debounce * 1000);
 		if (status < 0)
 			palmas_usb->sw_debounce_jiffies = msecs_to_jiffies(debounce);
 	}

 	INIT_DELAYED_WORK(&palmas_usb->wq_detectid, palmas_gpio_id_detect);

 	palmas->usb = palmas_usb;
 	palmas_usb->palmas = palmas;

 	palmas_usb->dev	 = &pdev->dev;

 	palmas_usb_wakeup(palmas, palmas_usb->wakeup);

 	platform_set_drvdata(pdev, palmas_usb);

 	palmas_usb->edev = devm_extcon_dev_allocate(&pdev->dev,
 						    palmas_extcon_cable);
 	if (IS_ERR(palmas_usb->edev)) {
 		dev_err(&pdev->dev, "failed to allocate extcon device\n");
 		return -ENOMEM;
 	}

 	status = devm_extcon_dev_register(&pdev->dev, palmas_usb->edev);
 	if (status) {
 		dev_err(&pdev->dev, "failed to register extcon device\n");
 		return status;
 	}

 	if (palmas_usb->enable_id_detection) {
 		palmas_usb->id_otg_irq = regmap_irq_get_virq(palmas->irq_data,
 							     PALMAS_ID_OTG_IRQ);
 		palmas_usb->id_irq = regmap_irq_get_virq(palmas->irq_data,
 							 PALMAS_ID_IRQ);
 		status = devm_request_threaded_irq(palmas_usb->dev,
 				palmas_usb->id_irq,
 				NULL, palmas_id_irq_handler,
 				IRQF_TRIGGER_FALLING | IRQF_TRIGGER_RISING |
 				IRQF_ONESHOT,
 				"palmas_usb_id", palmas_usb);
 		if (status < 0) {
 			dev_err(&pdev->dev, "can't get IRQ %d, err %d\n",
 					palmas_usb->id_irq, status);
 			return status;
 		}
 	} else if (palmas_usb->enable_gpio_id_detection) {
 		palmas_usb->gpio_id_irq = gpiod_to_irq(palmas_usb->id_gpiod);
 		if (palmas_usb->gpio_id_irq < 0) {
 			dev_err(&pdev->dev, "failed to get id irq\n");
 			return palmas_usb->gpio_id_irq;
 		}
 		status = devm_request_threaded_irq(&pdev->dev,
 						   palmas_usb->gpio_id_irq,
 						   NULL,
 						   palmas_gpio_id_irq_handler,
 						   IRQF_TRIGGER_RISING |
 						   IRQF_TRIGGER_FALLING |
 						   IRQF_ONESHOT,
 						   "palmas_usb_id",
 						   palmas_usb);
 		if (status < 0) {
 			dev_err(&pdev->dev,
 				"failed to request handler for id irq\n");
 			return status;
 		}
 	}

 	if (palmas_usb->enable_vbus_detection) {
 		palmas_usb->vbus_otg_irq = regmap_irq_get_virq(palmas->irq_data,
 						       PALMAS_VBUS_OTG_IRQ);
 		palmas_usb->vbus_irq = regmap_irq_get_virq(palmas->irq_data,
 							   PALMAS_VBUS_IRQ);
 		status = devm_request_threaded_irq(palmas_usb->dev,
 				palmas_usb->vbus_irq, NULL,
 				palmas_vbus_irq_handler,
 				IRQF_TRIGGER_FALLING | IRQF_TRIGGER_RISING |
 				IRQF_ONESHOT,
 				"palmas_usb_vbus", palmas_usb);
 		if (status < 0) {
 			dev_err(&pdev->dev, "can't get IRQ %d, err %d\n",
 					palmas_usb->vbus_irq, status);
 			return status;
 		}
 	} else if (palmas_usb->enable_gpio_vbus_detection) {
 		/* remux GPIO_1 as VBUSDET */
 		status = palmas_update_bits(palmas,
 			PALMAS_PU_PD_OD_BASE,
 			PALMAS_PRIMARY_SECONDARY_PAD1,
 			PALMAS_PRIMARY_SECONDARY_PAD1_GPIO_1_MASK,
 			(1 << PALMAS_PRIMARY_SECONDARY_PAD1_GPIO_1_SHIFT));
 		if (status < 0) {
 			dev_err(&pdev->dev, "can't remux GPIO1\n");
 			return status;
 		}

 		palmas_usb->vbus_otg_irq = regmap_irq_get_virq(palmas->irq_data,
 						       PALMAS_VBUS_OTG_IRQ);
 		palmas_usb->gpio_vbus_irq = gpiod_to_irq(palmas_usb->vbus_gpiod);
 		if (palmas_usb->gpio_vbus_irq < 0) {
 			dev_err(&pdev->dev, "failed to get vbus irq\n");
 			return palmas_usb->gpio_vbus_irq;
 		}
 		status = devm_request_threaded_irq(&pdev->dev,
 						palmas_usb->gpio_vbus_irq,
 						NULL,
 						palmas_vbus_irq_handler,
 						IRQF_TRIGGER_FALLING |
 						IRQF_TRIGGER_RISING |
-						IRQF_ONESHOT |
-						IRQF_EARLY_RESUME,
+						IRQF_ONESHOT,
 						"palmas_usb_vbus",
 						palmas_usb);
 		if (status < 0) {
 			dev_err(&pdev->dev,
 				"failed to request handler for vbus irq\n");
 			return status;
 		}
 	}

 	palmas_enable_irq(palmas_usb);
 	/* perform initial detection */
 	palmas_gpio_id_detect(&palmas_usb->wq_detectid.work);
 	device_set_wakeup_capable(&pdev->dev, true);
 	return 0;
 }



